) {
  final extra = fields != null && fields.isNotEmpty
      ? 'fields=${Uri.encodeQueryComponent(fields.join(','))}'
      : r'$expand=relations';
  final url = '${config.baseUrl}/wit/workitems'
      '?ids=${ids.join(',')}&$extra&api-version=$_adoApiVersion';
